import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController, NavController } from '@ionic/angular';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UploadService } from 'src/app/services/emis/upload.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { ViewImagePage } from 'src/app/pages/commonpages/view-image/view-image.page';
import { AlertService } from 'src/app/services/alert.service';
@Component({
  selector: 'app-my-inspections2',
  templateUrl: './my-inspections2.page.html',
  styleUrls: ['./my-inspections2.page.scss'],
})
export class MyInspections2Page implements OnInit {
  inspectionList         : any=[];
  teacher_id             : number;
  showList               : boolean;
  QuestAnswer            : boolean
  resultData             : any=[];
  image                  : any;

  constructor(private router :Router,private navCtrl:NavController, private emisService:EmisService, private userSessionService:UserSessionService,
    private uploadService: UploadService,private modalCtrl: ModalController,private alertService:AlertService) { }

  ngOnInit() {
  }

  ionViewDidEnter(){
  this.showList    = true;
  this.QuestAnswer = false;
  // this.teacher_id  = this.userSessionService.teacher_id(); 
  this.teacher_id  = this.userSessionService.emis_username();
  this.getMyInspectionsServer();

}
  
  getMyInspectionsServer() {
    this.emisService.getMyInspectionListUpdated(this.teacher_id, 1).subscribe((res) => {    
        if (res.result && res.result.length > 0) {                   
          this.inspectionList = [];
          res.result.forEach(element => {
            this.inspectionList.push(element);
          });                   
          this.showList = true;
          // this.insertMyInspections(res.result);
          this.inspectionList.reverse();
        }
        else {                  
          this.showList = false;
        }
      });
  }

  moveInspection(resultData:any){
  // console.log("navigate to vol-inpsection2 page", resultData);
  this.resultData = [];
  resultData.forEach(element => {
    this.resultData.push(element);
  })  
  this.QuestAnswer = true;
  }


  async viewImage(imageName) {
    // console.log("imagename",imageName);    
    var bucketName = "renewalapplicationemis";
    // Dummy image
    // imageName ='a926d470-6fc8-11ed-a171-2700209804e4.jpg'
    var filename = imageName;
    let expiry: number = 1800;
    this.uploadService.getUploadedFiles(bucketName, filename, expiry).subscribe(async (result) => {
      if (result) {
        this.image = result.url;
        const modal = await this.modalCtrl.create({
          component: ViewImagePage,
          componentProps: { image: this.image },
          cssClass: 'view-image-modal'
        });
        await modal.present();
      }
      else {
        this.alertService.error('Error in getting image file');
      }
    });
  }


  goBack(){
    if(this.QuestAnswer){
     this.QuestAnswer = false;
    }else{ 
    this.router.navigate(['tabs/itk-center-dashboard'])} 
  }
}
